package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.util.List;import java.nio.file.*;
public class LayoutAuditRedactionTest {
 private MaaImageBufferAudit.Result result(){return new MaaImageBufferAudit.Result(MaaImageBufferAudit.Status.VERIFIED_EQUAL,MaaImageBufferAudit.Sample.notRun(),MaaImageBufferAudit.Sample.notRun(),new MaaImageBufferAudit.CvSample(true,com.aliothmoon.maafw.rewards.RewardRegionLocator.Status.NO_CARDS,1,List.of(new com.aliothmoon.maafw.rewards.RewardRegionLocator.Box(101,202,303,404)),false),new MaaImageBufferAudit.OcrGeometry(true,1,1,false,List.of(new MaaImageBufferAudit.OcrRowBox(111,222,333,444,.987654))),1,true,true,true,true,true,true,true);}
 @Test public void compactSummaryCannotExposeOriginalRowsOrCvBoxes(){String s=result().compactSummary();assertTrue(s.contains("rowMetadata=SUPPRESSED cvGeometry=SUPPRESSED"));for(String token:new String[]{"111","222","333","444","101","202","303","404","0.987654","rows=[","originalXywh","fullFrameBoxes","allOcrGeometryDiagnosticOnly"})assertFalse(token,s.contains(token));assertTrue(s.contains("status=VERIFIED_EQUAL"));assertTrue(s.contains("positiveTaskBound=true"));assertTrue(s.contains("cleanupQualified=true"));}
 @Test public void legacySummaryRemainsUnchangedForOldModes(){String s=result().summary();assertTrue(s.contains("allOcrGeometryDiagnosticOnly="));assertTrue(s.contains("111,222,333,444@0.987654"));assertTrue(s.contains("fullFrameBoxes="));}
 @Test public void everyCheckpointReportUsesCompactAndSkipsLegacyCardGeometry()throws Exception{String s=Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once/CaptureSessionRuntime.java"));assertTrue(s.contains("returnReadIntent.layoutDiagnostic()?audit.compactSummary():audit.summary()"));assertTrue(s.contains("nativeImage=returnReadIntent!=null&&returnReadIntent.layoutDiagnostic()?audit.compactSummary():audit.summary()"));assertTrue(s.contains("if(!returnReadIntent.layoutDiagnostic()&&readOnlyObservation!=null&&readOnlyObservation.frame.diagnostic()!=null)details+="));}
}
